use crate::ciphers::rc4::cipher::rc4_encrypt;
use crate::ciphers::rc4::keys::rc4_default_key;
use crate::core::sample::sample_bytes;
use crate::core::timer::Stopwatch;

/// Time one encryption pass over `input_len` generated bytes.
pub fn rc4_measure(input_len: usize) -> u128 {
    let data = sample_bytes(input_len);
    let key = rc4_default_key();
    let watch = Stopwatch::start();
    let sealed = rc4_encrypt(&data, key);
    std::hint::black_box(sealed.len());
    watch.elapsed_ns()
}
